const updateHumanRequestComment = `-- name: UpdateHumanRequestComment :one
WITH changed AS (
    UPDATE comment AS c SET content = $1, revision = c.revision + 1, updated_at = now()
    WHERE c.human_request_id = $2 AND c.workspace_id = $3 AND c.deleted_at IS NULL
    RETURNING c.id, c.issue_id, c.author_type, c.author_id, c.content, c.type, c.created_at, c.updated_at, c.parent_id, c.workspace_id, c.resolved_at, c.resolved_by_type, c.resolved_by_id, c.source_task_id, c.quick_action_id, c.via_plugin_id, c.revision, c.recovery_settled_at, c.deleted_at, c.suppressed_agent_ids, c.human_request_id
), touched AS (
    UPDATE issue SET revision = issue.revision + 1,
        last_activity_at = GREATEST(COALESCE(issue.last_activity_at, issue.updated_at), now())
    FROM changed WHERE issue.id = changed.issue_id AND issue.workspace_id = changed.workspace_id
    RETURNING issue.id
)
SELECT changed.id, changed.issue_id, changed.author_type, changed.author_id, changed.content, changed.type, changed.created_at, changed.updated_at, changed.parent_id, changed.workspace_id, changed.resolved_at, changed.resolved_by_type, changed.resolved_by_id, changed.source_task_id, changed.quick_action_id, changed.via_plugin_id, changed.revision, changed.recovery_settled_at, changed.deleted_at, changed.suppressed_agent_ids, changed.human_request_id FROM changed CROSS JOIN (SELECT count(*) FROM touched) AS owner_update
`

